<?php

namespace Saad\AiKit\Rag\Text;

use Normalizer;

/**
 * The fleet's ONE match-side text folding contract for Arabic + English
 * search — what a query and an indexed text are both reduced to before they
 * are compared. Ported byte-for-byte from catodemy's
 * `App\Services\Search\SearchQueryText` + `App\Support\ArabicText` +
 * `App\Support\Numerals` (origin/main fc11c288); the shared fixture
 * `tests/Fixtures/rag/normalize.json` was GENERATED by running that code, and
 * both this class and its TypeScript twin (`js/rag/normalize.ts`) are tested
 * against it, so server, client and the existing catodemy indexes agree.
 *
 * Two layers, in order:
 *
 *  1. {@see canonicalize()} — recover the characters a document was always
 *     meant to contain: Arabic presentation forms (shaped PDF glyphs) fold to
 *     letters, zero-width and bidi controls are dropped, words a PDF extractor
 *     shattered into single letters («م ث ال») are rejoined, and the result is
 *     NFC-composed. A no-op on normally typed text. NOT 1:1 in characters.
 *  2. The fold — strip tashkeel + tatweel + superscript alef, fold alef
 *     variants (أ/إ/آ → ا), teh marbuta (ة → ه), alef maqsura (ى → ي), the
 *     hamza carriers (ؤ/ئ → ء), and Arabic-Indic / Persian digits to ASCII.
 *     Every step after {@see stripMarks()} is 1:1 in characters, so positions
 *     in a folded string map straight back to the mark-stripped text.
 *
 * Folding is MATCH-ONLY: stored and displayed text keeps the author's own
 * orthography. Lowercasing is a separate, explicit step
 * ({@see normalizeLower()}), because a Postgres `'simple'` tsvector already
 * lowercases and a title ILIKE needs `lower()` in SQL to agree.
 *
 * THE CONSTANTS ARE INDEX DDL. An app that interpolates {@see TRANSLATE_FROM}
 * / {@see TRANSLATE_TO} into a Postgres `translate()` expression index must
 * keep them byte-identical to what the index was built with — changing any
 * of them is a rebuild migration in every consuming app, not an edit here.
 */
final class ArabicNormalizer
{
    /**
     * Tashkeel (fathatan … sukun), tatweel and superscript alef (U+0670) —
     * deleted, so «مُحاضَرة» matches «محاضرة». They have no counterpart in the
     * to-string, which is exactly how SQL `translate()` deletes them.
     */
    public const MARKS = 'ًٌٍَُِّْـٰ';

    /**
     * Orthography folding, char for char: alef variants → bare alef, teh
     * marbuta → heh, alef maqsura → yeh, hamza carriers → bare hamza (so
     * «مسؤول» / «مسئول» / «مسءول» all fold to «مسءول»). catodemy owner
     * decision 2026-08-05 — the hamza carriers fold to ء, not to و/ي.
     */
    public const FOLD_FROM = 'أإآةىؤئ';

    public const FOLD_TO = 'اااهيءء';

    /** Arabic-Indic (U+0660–0669) and Persian (U+06F0–06F9) digits → ASCII. */
    public const DIGITS_FROM = '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹';

    public const DIGITS_TO = '01234567890123456789';

    /**
     * The ONE `translate()` argument pair: every mapped char sits in the
     * prefix that lines up with the to-string; the marks trail past its end
     * so `translate()` deletes them.
     */
    public const TRANSLATE_FROM = self::FOLD_FROM.self::DIGITS_FROM.self::MARKS;

    public const TRANSLATE_TO = self::FOLD_TO.self::DIGITS_TO;

    /**
     * tsquery metacharacters (and quotes/backslash) — replaced by a space
     * before tokenising, so user input can never reach `to_tsquery` raw.
     */
    public const TOKEN_STRIP_PATTERN = '/[&|!():*\'"`\\\\<>]+/u';

    /**
     * Arabic Presentation Forms-A and -B. U+FEFD/FEFE are unassigned and
     * U+FEFF is ZWNBSP (a control, stripped instead), so the range stops at
     * U+FEFC.
     */
    private const PRESENTATION_FORMS = '/[\x{FB50}-\x{FDFF}\x{FE70}-\x{FEFC}]/u';

    /**
     * Zero-width space/joiners, LRM/RLM, the bidi embedding/override controls,
     * the bidi isolates and ZWNBSP/BOM.
     */
    private const INVISIBLE_CONTROLS = '/[\x{200B}-\x{200F}\x{202A}-\x{202E}\x{2066}-\x{2069}\x{FEFF}]/u';

    /** Arabic LETTERS only — no tashkeel, tatweel, digits or punctuation. */
    private const LETTER = '\x{0621}-\x{063A}\x{0641}-\x{064A}\x{0671}-\x{06D3}\x{06FA}-\x{06FF}';

    /**
     * Full match-side normalisation: canonicalise, strip marks, fold
     * orthography, fold digits. Case is kept — see {@see normalizeLower()}.
     */
    public static function normalize(string $text): string
    {
        return self::normalizeDigits(self::foldOrthography(self::stripMarks(
            self::canonicalize($text)
        )));
    }

    /**
     * {@see normalize()} plus lowercasing — the PHP twin of
     * `translate(lower(col), FROM, TO)`, for title/phrase matching.
     */
    public static function normalizeLower(string $text): string
    {
        return mb_strtolower(self::normalize($text));
    }

    /**
     * Normalised, metacharacter-free query terms: {@see normalize()}, replace
     * tsquery metacharacters with spaces, split on whitespace. Case is kept
     * (a `'simple'` tsquery lowercases on its own).
     *
     * @return list<string>
     */
    public static function tokens(string $text): array
    {
        $cleaned = (string) preg_replace(self::TOKEN_STRIP_PATTERN, ' ', self::normalize($text));

        return preg_split('/\s+/u', trim($cleaned), -1, PREG_SPLIT_NO_EMPTY) ?: [];
    }

    /** Delete tashkeel, tatweel and superscript alef (display-safe). */
    public static function stripMarks(string $text): string
    {
        return str_replace(mb_str_split(self::MARKS), '', $text);
    }

    /** Fold orthography variants, 1:1 in characters. */
    public static function foldOrthography(string $text): string
    {
        return strtr($text, array_combine(
            mb_str_split(self::FOLD_FROM),
            mb_str_split(self::FOLD_TO),
        ));
    }

    /** Fold Arabic-Indic and Persian digits to ASCII, 1:1 in characters. */
    public static function normalizeDigits(string $text): string
    {
        if ($text === '') {
            return '';
        }

        $out = '';

        foreach (mb_str_split($text) as $char) {
            $code = mb_ord($char);

            if ($code >= 0x0660 && $code <= 0x0669) {
                $out .= (string) ($code - 0x0660);
            } elseif ($code >= 0x06F0 && $code <= 0x06F9) {
                $out .= (string) ($code - 0x06F0);
            } else {
                $out .= $char;
            }
        }

        return $out;
    }

    /**
     * The same folding as a Postgres expression over `$column` (a trusted
     * identifier or expression — never user input): one `translate()` with
     * the {@see TRANSLATE_FROM} / {@see TRANSLATE_TO} pair.
     */
    public static function translateSql(string $column): string
    {
        return "translate({$column}, '".self::TRANSLATE_FROM."', '".self::TRANSLATE_TO."')";
    }

    /**
     * Fold shaped glyphs back to letters, drop invisible controls, rejoin
     * shattered words, and NFC-compose. Idempotent, and a no-op on clean
     * text — which is what makes it safe on the query side too.
     */
    public static function canonicalize(string $text): string
    {
        if ($text === '') {
            return '';
        }

        return self::compose(
            self::joinShatteredWords(
                self::stripInvisibleControls(
                    self::foldPresentationForms($text)
                )
            )
        );
    }

    /**
     * Map every Arabic presentation form to its base letter(s) through that
     * CHARACTER's NFKC decomposition («ﺍ» → «ا», «ﻻ» → «لا», «ﷲ» → «الله»).
     * Per character, never a whole-string NFKC, which would also rewrite
     * «x²» to «x2».
     */
    public static function foldPresentationForms(string $text): string
    {
        if (! class_exists(Normalizer::class)) {
            return $text;
        }

        return (string) preg_replace_callback(
            self::PRESENTATION_FORMS,
            static function (array $match): string {
                $folded = Normalizer::normalize($match[0], Normalizer::FORM_KC);

                if ($folded === false) {
                    return $match[0];
                }

                // Isolated tashkeel forms decompose to SPACE + mark: keep the
                // mark, drop the space that would split the word.
                return str_starts_with($folded, ' ') ? substr($folded, 1) : $folded;
            },
            $text
        );
    }

    /** Remove zero-width and bidi control characters. */
    public static function stripInvisibleControls(string $text): string
    {
        return (string) preg_replace(self::INVISIBLE_CONTROLS, '', $text);
    }

    /**
     * Rejoin a word a PDF extractor emitted letter by letter («م ث ال»). Fires
     * only on the artefact's signature: a run of three or more Arabic-only
     * tokens of at most two letters, at least two of them single letters —
     * which genuine Arabic prose does not produce.
     */
    public static function joinShatteredWords(string $text): string
    {
        return (string) preg_replace_callback(
            '/(?<![^\s])(?:['.self::LETTER.']{1,2}(?:[ \t]+|$)){3,}/u',
            static function (array $match): string {
                $tokens = preg_split('/[ \t]+/u', trim($match[0]), -1, PREG_SPLIT_NO_EMPTY) ?: [];

                $singles = 0;
                foreach ($tokens as $token) {
                    if (mb_strlen($token) === 1) {
                        $singles++;
                    }
                }

                if ($singles < 2) {
                    return $match[0];
                }

                $trailing = preg_match('/[ \t]+$/u', $match[0], $tail) === 1 ? $tail[0] : '';

                return implode('', $tokens).$trailing;
            },
            $text
        );
    }

    /** Canonical composition (NFC, never NFKC): «ا» + U+0654 → «أ». */
    private static function compose(string $text): string
    {
        if (! class_exists(Normalizer::class)) {
            return $text;
        }

        $composed = Normalizer::normalize($text, Normalizer::FORM_C);

        return $composed === false ? $text : $composed;
    }
}
